//! Ownership markers on generated Markdown files: a frontmatter comment with a content hash.

const PREFIX: &str = "# generated by concordia studio sync from ";

/// What sync knows about a file it might own.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum Ownership {
    /// Generated by sync and unchanged since.
    Owned,
    /// Generated by sync, then edited by hand.
    Edited,
    /// Not generated by sync.
    Foreign,
}

/// Adds the marker as the first frontmatter line of `text` (which starts with `---\n`).
pub(crate) fn mark(text: &str, source: &str) -> String {
    let body = text.strip_prefix("---\n").unwrap_or(text);
    let unmarked = format!("---\n{body}");
    format!(
        "---\n{PREFIX}{source}; hash={}; do not edit\n{body}",
        hash(&unmarked)
    )
}

/// Whether `text` carries a marker, and whether its content still matches it.
pub(crate) fn ownership(text: &str) -> Ownership {
    let Some(rest) = text.strip_prefix("---\n") else {
        return Ownership::Foreign;
    };
    let Some((line, body)) = rest.split_once('\n') else {
        return Ownership::Foreign;
    };
    let Some(recorded) = line
        .strip_prefix(PREFIX)
        .and_then(|l| l.split("; hash=").nth(1))
        .and_then(|l| l.split(';').next())
    else {
        return Ownership::Foreign;
    };
    match hash(&format!("---\n{body}")) == recorded {
        true => Ownership::Owned,
        false => Ownership::Edited,
    }
}

/// The first 16 hex digits of the BLAKE3 hash of `text`.
fn hash(text: &str) -> String {
    blake3::hash(text.as_bytes()).to_hex()[..16].to_owned()
}
